    "slug": "landscaping-subcontractor-cost",
    "tag": "Landscaping",
    "name": "Landscaping",
    "cluster": "planning",
    "title": "Landscaping Subcontractor Cost: Compare Delivery Options",
    "seoTitle": "Landscaping Subcontractor Cost",
    "description": "Compare landscaping subcontractor cost with in-house delivery. Include coordination, materials, fees, freed hours and separate supplier capacity.",
    "metaDescription": "Compare landscaping subcontractor cost with in-house delivery. Include coordination, materials, fees, freed hours and separate supplier capacity.",
    "calculatorSlug": "landscaping-break-even-calculator",
